import {Store,Keys} from './app-store.js';
import {DAY_ONE,DAY_300,USERS,CHAPTERS,EVENTS,FIRSTS,MONTH_BOARDS,QUESTIONS,PLACES,CITIES,CONSTELLATION,SEASONS,SPECIALS,MORE_SPECIALS,FOOD_ENTRIES,BEFORE_CAME_TRUE} from './app-data.js';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pad=n=>String(n).padStart(2,'0');
const isoDate=d=>`${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`;
const todayISO=()=>isoDate(new Date());
const fmtDate=s=>new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',year:'numeric'}).format(new Date(`${s}T12:00:00`)).toUpperCase();
const weekday=s=>new Intl.DateTimeFormat('en-US',{weekday:'long'}).format(new Date(`${s}T12:00:00`)).toUpperCase();
const dayDiff=(a,b)=>Math.round((new Date(`${b}T12:00:00`)-new Date(`${a}T12:00:00`))/86400000);
const relationshipDay=s=>dayDiff(DAY_ONE,s)+1;
const uniqueDates=()=>[...new Set(EVENTS.map(e=>e.date))].sort();
const eventForDate=d=>EVENTS.filter(e=>e.date===d);
const primaryEvent=d=>eventForDate(d)[0]||{date:d,title:'Our Day',chapter:'continue',story:''};
const chapterBy=id=>CHAPTERS.find(c=>c.id===id)||CHAPTERS[0];
const sleep=n=>new Promise(r=>setTimeout(r,n));
const state={view:'home',sub:'',month:new Date(2025,9,1),daysMode:'calendar',futureTab:'postcards',albumMode:'story',albumSearch:'',albumType:'',user:localStorage.getItem('clean300_identity')||localStorage.getItem('v25_identity_user')||'',activity:[],selectedMood:'',kakao:null,renderSeq:0};
function toast(text){const root=$('#toast-root');const el=document.createElement('div');el.className='toast';el.textContent=text;root.append(el);setTimeout(()=>el.remove(),3000)}
function setOverlay(html){$('#overlay-root').innerHTML=html}function closeOverlay(){setOverlay('')}
function setActiveNav(){$$('.desktop-nav [data-target],.mobile-nav [data-target]').forEach(b=>b.classList.toggle('active',b.dataset.target===state.view))}
function currentUser(){return state.user||'시현'}function otherUser(u=currentUser()){return u==='시현'?'강원':'시현'}
function photoId(src){let h=2166136261;for(let i=0;i<src.length;i++){h^=src.charCodeAt(i);h=Math.imul(h,16777619)}return(h>>>0).toString(36)}
async function photos(date){return await Store.get(Keys.photos(date),[])}async function hero(date){return await Store.get(Keys.hero(date),null)}async function photoMeta(date,src){return await Store.get(Keys.photoMeta(date,photoId(src)),null)}async function setPhotoMeta(date,src,meta){return Store.set(Keys.photoMeta(date,photoId(src)),meta)}
function routeTo(view,sub=''){const path=`#/${view}${sub?'/'+sub:''}`;if(location.hash!==path)location.hash=path;else applyRoute()}
function parseRoute(){const bits=(location.hash.replace(/^#\/?/,'')||'home').split('/').filter(Boolean);const main=['home','days','diary','special','future'].includes(bits[0])?bits[0]:'home';return{view:main,sub:bits.slice(1).join('/')}}
async function applyRoute(){const r=parseRoute();state.view=r.view;state.sub=r.sub;setActiveNav();await renderView();window.scrollTo({top:0,behavior:'smooth'})}
function emptyPhoto(label='ADD A HERO PHOTO'){return`<div class="empty-photo"><b>${esc(label)}</b>NO SOURCE PHOTO = EMPTY FRAME</div>`}
async function statusFor(date,user){const[checkin,line,g,q]=await Promise.all([Store.get(Keys.daily(date,user),null),Store.get(Keys.dailyLine(date,user),null),Store.get(Keys.gratitude(date,user),null),Store.get(Keys.answer(date,user),null)]);const record=!!((checkin&&(checkin.mood||checkin.line||(checkin.activities||[]).length))||line?.text);return{record,gratitude:!!g?.text?.trim(),question:!!q?.text?.trim(),checkin,line,g,q}}
async function completion(date){const[s,g]=await Promise.all([statusFor(date,'시현'),statusFor(date,'강원')]);const total=[s.record,s.gratitude,s.question,g.record,g.gratitude,g.question].filter(Boolean).length;return{시현:s,강원:g,total}}
async function gratitudeStats(){const rows=await Store.entries('gratitude:');const map={};for(const[key,v]of rows){const m=key.match(/^gratitude:(\d{4}-\d{2}-\d{2}):(시현|강원)$/);if(!m||!v?.text?.trim())continue;(map[m[1]]??={})[m[2]]=true}const dates=Object.keys(map).filter(d=>map[d].시현&&map[d].강원).sort();let streak=0;if(dates.length){let cur=new Date(`${dates.at(-1)}T12:00:00`);for(let i=dates.length-1;i>=0;i--){if(dates[i]===isoDate(cur)){streak++;cur.setDate(cur.getDate()-1)}else break}}return{days:dates.length,streak,dates}}
function viewHead(kicker,title,desc,actions=''){return`<div class="view-head"><div class="copy"><span class="eyebrow">${esc(kicker)}</span><h1>${title}</h1><p>${desc}</p></div>${actions?`<div class="view-actions">${actions}</div>`:''}</div>`}
async function renderView(){const seq=++state.renderSeq,root=$('#view-root');root.innerHTML='<div class="panel">불러오는 중…</div>';let html='';if(state.view==='home')html=await renderHome();if(state.view==='days')html=await renderDays();if(state.view==='diary')html=await renderDiary();if(state.view==='special')html=await renderSpecial();if(state.view==='future')html=await renderFuture();if(seq!==state.renderSeq)return;root.innerHTML=html;root.focus({preventScroll:true})}
async function renderHome(){const today=todayISO(),comp=await completion(today),stats=await gratitudeStats();const heroDate=(await hero('2025-12-20'))?'2025-12-20':(await hero(DAY_ONE))?DAY_ONE:'2025-10-04';const heroImg=await hero(heroDate);const movie=await Promise.all(CHAPTERS.map(async(c,i)=>({c,i,img:await hero(c.start)})));const recent=state.activity.slice(0,5);return`<section class="hero"><div class="hero-copy"><span class="eyebrow">SIHYUN & GANGWON · OUR DIGITAL MEMORY ARCHIVE</span><h1>300 DAYS<span>WITH YOU</span></h1><div class="note">New York, 2025<br>and somehow, we met here.</div><div class="hero-actions"><button class="primary-btn" data-action="view" data-target="days">OPEN OUR DAYS</button><button class="secondary-btn" data-action="memory" data-date="2025-10-01">START FROM THE BEGINNING</button><button class="ghost-btn" data-action="memory" data-date="2025-10-23">GO TO DAY 1</button></div></div><div class="hero-photo"><span class="tape"></span><div class="photo-box">${heroImg?`<img src="${esc(heroImg)}" alt="Our hero photo">`:emptyPhoto('HERO PHOTO')}</div></div></section><section class="today-shell"><article class="panel today-card"><div class="today-date"><div><span class="panel-label">TODAY · DAILY US</span><h2>Our day, today.</h2><strong>${fmtDate(today)} · DAY ${relationshipDay(today)}</strong></div><span class="day-pill">${comp.total}/6</span></div><div class="completion-table"><div></div><div>시현</div><div>강원</div><div>OUR DAY</div><div class="done-dot">${comp.시현.record?'✓':'·'}</div><div class="done-dot">${comp.강원.record?'✓':'·'}</div><div>THANK YOU</div><div class="done-dot">${comp.시현.gratitude?'✓':'·'}</div><div class="done-dot">${comp.강원.gratitude?'✓':'·'}</div><div>QUESTION</div><div class="done-dot">${comp.시현.question?'✓':'·'}</div><div class="done-dot">${comp.강원.question?'✓':'·'}</div></div><div class="progress"><i style="width:${comp.total/6*100}%"></i></div><p><b>오늘 우리 ${comp.total} / 6 완료.</b> 완성된 하루는 OUR DAYS 안의 Daily Card로 남아요.</p><button class="primary-btn" data-action="view" data-target="diary">Continue today →</button><p class="hand">${stats.days} days of thanks · ${stats.streak} day streak</p></article><aside class="panel"><span class="panel-label">RECENT FROM US</span><h2>둘이 남긴 활동</h2><div class="activity-list">${recent.length?recent.map(a=>`<button class="activity-row" data-action="memory" data-date="${esc(a.date||today)}"><b>${esc(a.author||'우리')} · ${esc(activityLabel(a.type))}</b><span>${esc((a.text||'').slice(0,74))}</span></button>`).join(''):'<p>아직 새 활동이 없어요.</p>'}</div></aside></section><section class="film-section"><div class="view-head"><div class="copy"><span class="eyebrow">OUR STORY, AS A MOVIE</span><h2 class="section-title">Eight chapters, still going.</h2></div><button class="pill-btn" data-action="special" data-feature="story">FULL STORY →</button></div><div class="film-strip">${movie.map(({c,i,img})=>`<button class="film-card" data-action="memory" data-date="${c.start}"><div class="film-image">${img?`<img src="${esc(img)}" alt="">`:emptyPhoto('CHAPTER STILL')}</div><div class="film-copy"><small>0${i+1}</small><strong>${esc(c.label)}</strong><em>${esc(c.sub)}</em></div></button>`).join('')}</div></section><section class="film-section"><div class="view-head"><div class="copy"><span class="eyebrow">BY MONTH / CHAPTER</span><h2 class="section-title">A scrapbook route through us.</h2></div></div><div class="month-board">${MONTH_BOARDS.map(m=>`<button class="month-card" data-action="memory" data-date="${m.date}"><b>${esc(m.label)}</b><strong>${esc(m.title)}</strong><span>${esc(m.sub)}</span></button>`).join('')}</div></section>`}
function activityLabel(t){return({gratitude:'감사',record:'하루 기록',question:'질문 답변',photo:'사진',future:'Future',comment:'댓글'}[t]||'활동')}
async function renderDays(){const y=state.month.getFullYear(),m=state.month.getMonth(),ym=`${y}-${pad(m+1)}`;const modeBtns=`<button class="pill-btn ${state.daysMode==='calendar'?'active':''}" data-action="days-mode" data-mode="calendar">CALENDAR</button><button class="pill-btn ${state.daysMode==='list'?'active':''}" data-action="days-mode" data-mode="list">LIST</button>`;const monthEvents=EVENTS.filter(e=>e.date.startsWith(ym));const dates=[...new Set(monthEvents.map(e=>e.date))];const heroPairs=await Promise.all(dates.map(async d=>[d,await hero(d)]));const heroMap=Object.fromEntries(heroPairs);const checkKeys=await Store.keys(`checkin:${ym}`),moodMap={};for(const k of checkKeys){const mt=k.match(/^checkin:(\d{4}-\d{2}-\d{2}):(시현|강원)$/);if(!mt)continue;const v=await Store.get(k,null);if(v?.mood)(moodMap[mt[1]]??=[]).push(v.mood)}let body='';if(state.daysMode==='calendar'){const first=new Date(y,m,1),daysIn=new Date(y,m+1,0).getDate(),cells=[];for(let i=0;i<first.getDay();i++)cells.push('<button class="day-cell empty" tabindex="-1"></button>');for(let d=1;d<=daysIn;d++){const ds=`${ym}-${pad(d)}`,ev=primaryEvent(ds),has=eventForDate(ds).length>0,h=heroMap[ds],moods=moodMap[ds]||[];cells.push(`<button class="day-cell ${has?'has-event':''} ${ds===todayISO()?'today':''}" data-action="memory" data-date="${ds}">${h?`<img src="${esc(h)}" alt="">`:''}<span class="num">${d}</span>${moods.length?`<span class="mood-dots">${moods.slice(0,2).map(()=>'<i class="mood-dot"></i>').join('')}</span>`:''}${has?`<span class="event-title">${esc(ev.title)}</span>`:''}</button>`)}body=`<div class="calendar">${['SUN','MON','TUE','WED','THU','FRI','SAT'].map(x=>`<div class="weekday">${x}</div>`).join('')}${cells.join('')}</div>`}else body=`<div class="month-list">${dates.length?dates.map(d=>{const evs=eventForDate(d);return`<button class="month-row" data-action="memory" data-date="${d}"><span class="date">${fmtDate(d).replace(/, \d{4}/,'')}</span><strong>${esc(evs.map(e=>e.title).join(' · '))}</strong><span class="arrow">→</span></button>`}).join(''):'<div class="panel">이 달에는 아직 기록된 날짜가 없어요.</div>'}</div>`;const report=await monthlyReport(ym,monthEvents,checkKeys);return`${viewHead('OUR DAYS','Our Days','모든 날짜를 달력과 목록으로 보고, 한 번 터치하면 같은 Memory Detail로 들어갑니다.',modeBtns)}<div class="panel"><div class="calendar-toolbar"><div class="calendar-nav"><button class="round-btn" data-action="month-shift" data-delta="-1">←</button><strong>${new Intl.DateTimeFormat('en-US',{month:'long',year:'numeric'}).format(state.month)}</strong><button class="round-btn" data-action="month-shift" data-delta="1">→</button></div><span class="hand muted">${dates.length} recorded days</span></div>${body}</div><div class="panel"><span class="panel-label">MONTHLY LOVE REPORT</span><h2>${new Intl.DateTimeFormat('en-US',{month:'long',year:'numeric'}).format(state.month)}</h2><div class="report-grid">${report.map(r=>`<div class="report-card"><b>${esc(r.label)}</b><strong>${esc(r.value)}</strong><span>${esc(r.sub)}</span></div>`).join('')}</div></div>`}
async function monthlyReport(ym,monthEvents,checkKeys){const moods=[],acts=[];for(const k of checkKeys){const v=await Store.get(k,null);if(v?.mood)moods.push(v.mood);if(v?.activities)acts.push(...v.activities)}const count=a=>a.reduce((o,x)=>(o[x]=(o[x]||0)+1,o),{}),top=a=>{const c=count(a);return Object.keys(c).sort((x,y)=>c[y]-c[x])[0]||'—'};const hard=moods.filter(x=>['서운함','속상함','화남'].includes(x)).length,dateDays=new Set(monthEvents.filter(e=>e.location||e.layout==='cinema'||e.layout==='map').map(e=>e.date)).size,kak=state.kakao?.months?.[ym]||null;return[{label:'Mostly',value:top(moods),sub:'가장 자주 기록된 감정'},{label:'Hard days',value:String(hard),sub:'서운함 · 속상함 · 화남 기록'},{label:'Date days',value:String(dateDays),sub:'기록된 데이트/나들이'},{label:'Most common date',value:top(acts),sub:'가장 자주 선택한 활동'},{label:'Affection pulse',value:kak?`${kak.affectionRate.toFixed(1)}`:'—',sub:'1,000 messages 당 애정 표현'},{label:'“사랑해”',value:kak?String(kak.words['사랑해']||0):'—',sub:'Kakao import 기준'}]}
const MOODS=['🥰 두근거림','😊 행복','😌 편안함','🥹 애틋함','💭 보고싶음','🤍 고마움','😔 서운함','😢 속상함','😠 화남'];function questionFor(date){const idx=Math.abs(dayDiff('2025-01-01',date))%QUESTIONS.length;return{id:idx,text:QUESTIONS[idx]}}
async function renderDiary(){const date=todayISO(),u=currentUser(),p=otherUser(),comp=await completion(date),mine=comp[u],partner=comp[p],ps=await photos(date),stats=await gratitudeStats(),q=questionFor(date),myQ=await Store.get(Keys.answer(date,u),null),partnerQ=await Store.get(Keys.answer(date,p),null),myG=await Store.get(Keys.gratitude(date,u),null),partnerG=await Store.get(Keys.gratitude(date,p),null),check=await Store.get(Keys.daily(date,u),null);state.selectedMood=check?.mood||'';const bothG=!!myG?.text?.trim()&&!!partnerG?.text?.trim(),bothQ=!!myQ?.text?.trim()&&!!partnerQ?.text?.trim(),photoSlots=[0,1,2].map(i=>`<div class="photo-box">${ps[i]?`<img src="${esc(ps[i])}" alt="오늘 사진 ${i+1}">`:emptyPhoto('BLANK PHOTO SLOT')}</div>`).join(''),stars=Array.from({length:Math.min(stats.days,55)},()=>'<i>★</i>').join('');return`${viewHead('OUR PHOTO DIARY','Keep the days we actually lived.','오늘의 실제 사진을 먼저 남기고, 그날의 마음과 고마움, 서로의 답을 기록합니다.')}<div class="diary-layout"><div class="diary-stack"><section class="diary-card"><span class="panel-label">01 · TODAY'S PHOTOS</span><h3>Save the day as it looked.</h3><div class="today-photos">${photoSlots}</div><div class="save-row"><span class="hand muted">${ps.length} PHOTOS</span><div><button class="secondary-btn" data-action="upload" data-date="${date}">오늘 사진 추가</button> <button class="ghost-btn" data-action="special" data-feature="album">PHOTO ALBUM</button></div></div></section><section class="diary-card"><span class="panel-label">02 · OUR DAY</span><h3>오늘 우리에게 있었던 일</h3><div class="mood-grid">${MOODS.map(x=>`<button class="mood-btn ${state.selectedMood===x?'active':''}" data-action="mood" data-value="${esc(x)}">${esc(x)}</button>`).join('')}</div><div class="field"><label>오늘 우리에게 있었던 일을 한 줄로 남겨요.</label><textarea id="diary-line" placeholder="오늘의 우리를 한 줄로…">${esc(check?.line||mine.line?.text||'')}</textarea></div><div class="save-row"><span id="diary-save-state" class="saved-label"></span><button class="primary-btn" data-action="save-day">오늘 기록 저장</button></div></section><section class="diary-card"><span class="panel-label">03 · THANK YOU</span><h3>오늘 ${p}에게 고마웠던 것 하나</h3><div class="field"><textarea id="gratitude-input" placeholder="오늘 고마웠던 순간 하나…">${esc(myG?.text||'')}</textarea></div><div class="save-row"><span id="gratitude-state" class="saved-label"></span><button class="primary-btn" data-action="save-gratitude">감사 저장</button></div>${bothG?`<div class="reveal-grid"><div class="letter-card"><b>FROM ${u}</b><p>${esc(myG.text)}</p></div><div class="letter-card"><b>FROM ${p}</b><p>${esc(partnerG.text)}</p></div></div>`:partnerG?.text?.trim()?`<div class="reveal-lock">💌 ${p}의 감사가 도착했어요.<br>내가 남기면 함께 열려요.</div>`:''}</section><section class="diary-card"><span class="panel-label">04 · TODAY'S QUESTION</span><h3>${esc(q.text)}</h3><div class="field"><textarea id="question-input" placeholder="내 답을 먼저 남겨요.">${esc(myQ?.text||'')}</textarea></div><div class="save-row"><span id="question-state" class="saved-label"></span><button class="primary-btn" data-action="save-question" data-qid="${q.id}">답변 저장</button></div>${bothQ?`<div class="reveal-grid"><div class="letter-card"><b>${u}</b><p>${esc(myQ.text)}</p></div><div class="letter-card"><b>${p}</b><p>${esc(partnerQ.text)}</p></div></div>`:partnerQ?.text?.trim()?`<div class="reveal-lock">${p}의 답이 도착했어요.<br>내가 답하면 OUR ANSWERS가 열려요.</div>`:''}</section><section class="diary-card"><span class="panel-label">DAILY COMPLETION</span><h3>${comp.total===6?'Today is saved.':'Today is still being written.'}</h3><div class="progress"><i style="width:${comp.total/6*100}%"></i></div><p>${comp.total} / 6 · ${comp.total===6?'Another day of us.':'시현 3개 + 강원 3개를 함께 채워요.'}</p><button class="secondary-btn" data-action="memory" data-date="${date}">오늘 카드 보기 →</button></section></div><aside class="diary-stack"><section class="diary-card"><span class="panel-label">OUR THANK-YOU JAR</span><div class="jar"><div class="jar-stars">${stars}</div></div><div class="jar-stats"><strong>${stats.days} days</strong><span class="hand">${stats.streak} day streak</span></div></section>${renderReminderSettings()}</aside></div>`}
function renderReminderSettings(){const on=localStorage.getItem('clean300_daily_reminder')==='1',partner=localStorage.getItem('clean300_partner_notify')==='1',time=localStorage.getItem('clean300_reminder_time')||'21:30';return`<section class="diary-card"><span class="panel-label">REMINDERS</span><h3>Keep our day open.</h3><div class="settings-list"><label class="setting-row"><span>Daily reminder</span><input type="checkbox" data-setting="daily" ${on?'checked':''}></label><label class="setting-row"><span>Reminder time</span><input type="time" data-setting="time" value="${time}"></label><label class="setting-row"><span>상대방 활동 알림</span><input type="checkbox" data-setting="partner" ${partner?'checked':''}></label><button class="secondary-btn" data-action="notification-permission">브라우저 알림 허용</button></div><p>브라우저가 열려 있을 때 정확히 동작합니다. 앱이 완전히 종료된 상태의 진짜 백그라운드 푸시는 별도 서버/FCM 구성이 필요합니다.</p></section>`}
async function renderSpecial(){if(state.sub)return renderSpecialFeature(state.sub);return`${viewHead('SPECIAL FEATURES','Our Little Museum','날짜순이 아닌 방식으로 우리를 다시 보는 작은 전시관.')}<div class="special-grid">${SPECIALS.map(([id,t,s])=>`<button class="special-card" data-action="special" data-feature="${id}"><b>SPECIAL</b><strong>${t}</strong><span>${s}</span></button>`).join('')}</div><div class="panel"><span class="panel-label">MORE OF US</span><div class="more-shelf">${MORE_SPECIALS.map(([id,t])=>`<button data-action="special" data-feature="${id}">${t}</button>`).join('')}</div></div>`}
async function renderSpecialFeature(id){const back=`<button class="pill-btn" data-action="special-back">← SPECIAL</button>`;if(id==='story')return renderStory(back);if(id==='album')return renderAlbum(back);if(id==='search')return`${viewHead('GLOBAL SEARCH','Find a memory.','날짜 · 장소 · 음식 · 느낌 · 캡션 · 카톡 문구를 검색합니다.',back)}${searchPanel('')}`;if(id==='firsts')return renderFirsts(back);if(id==='places')return renderPlaces(back);if(id==='constellation')return renderConstellation(back);if(id==='posters')return renderPosters(back);if(id==='words')return renderWords(back);if(id==='seasons')return renderSeasons(back);if(id==='food')return renderFood(back);if(id==='numbers')return renderNumbers(back);if(id==='pulse')return renderPulse(back);if(id==='awards')return renderAwards(back);if(id==='photobooth')return renderPhotobooth(back);if(id==='favorites')return renderFavorites(back);if(id==='liked')return renderLiked(back);if(id==='thanks')return renderThanks(back);if(id==='beforecame')return renderBeforeCame(back);if(id==='funny')return renderFunny(back);return`${viewHead('SPECIAL','Coming soon.','이 기능은 clean architecture 안에서 다음 단계로 확장할 수 있어요.',back)}`}
async function renderStory(back=''){const blocks=CHAPTERS.map(c=>{const list=EVENTS.filter(e=>e.chapter===c.id);return`<section class="panel"><span class="panel-label">${esc(c.sub)}</span><h2>${esc(c.label)}</h2><div class="timeline">${list.map(e=>`<button class="timeline-item ${e.special?'special':''}" data-action="memory" data-date="${e.date}"><small>${fmtDate(e.date)}</small><strong>${esc(e.title)}</strong></button>`).join('')}</div></section>`}).join('');return`${viewHead('OUR STORY, AS A MOVIE','The Story','서로 다른 인생에서 시작해 New York, West Coast, Korea, Long Distance, 그리고 300일까지.',back)}${blocks}`}
async function renderFirsts(back=''){const rows=await Promise.all(FIRSTS.map(async([d,l])=>({d,l,h:await hero(d)})));return`${viewHead('OUR FIRSTS','The first time for everything.','사진이 없으면 빈 프레임으로 남깁니다.',back)}<div class="first-grid">${rows.map(x=>`<button class="first-card" data-action="memory" data-date="${x.d}"><div class="thumb">${x.h?`<img src="${esc(x.h)}" alt="">`:emptyPhoto('FIRST')}</div><div class="copy"><small>${fmtDate(x.d)}</small><strong>${esc(x.l)}</strong></div></button>`).join('')}</div>`}
async function renderPlaces(back=''){return`${viewHead('OUR NEW YORK','A city full of us.','Google Map이 아니라 우리 기억 중심의 scrapbook place board.',back)}<div class="panel"><div class="place-board">${PLACES.map(([p,d])=>`<button class="place-pin" data-action="memory" data-date="${d}"><b>${esc(p)}</b><span>${fmtDate(d).replace(/, \d{4}/,'')}</span></button>`).join('')}</div></div><div class="panel"><span class="panel-label">CITIES WE SHARED</span><h2>Beyond New York.</h2><div class="word-cloud">${CITIES.map(c=>`<button class="word-chip" data-action="city-search" data-city="${esc(c)}">${esc(c)}</button>`).join('')}</div></div>`}
function renderConstellation(back=''){const pos=[[11,24],[32,38],[51,22],[70,39],[84,19],[25,72],[56,77],[82,70]];return`${viewHead('OUR CONSTELLATION','The dates that became stars.','별 하나를 누르면 그 날짜의 Memory Detail이 열립니다.',back)}<div class="constellation">${CONSTELLATION.map(([d,l],i)=>`<button class="star-btn" style="left:${pos[i][0]}%;top:${pos[i][1]}%" data-action="memory" data-date="${d}"><i></i><b>${esc(l)}<br>${d.slice(5)}</b></button>`).join('')}</div>`}
async function renderPosters(back=''){const dates=['2025-10-04','2025-11-01','2025-11-19','2025-12-08','2025-12-20','2025-12-30','2026-01-10','2026-03-21'],rows=await Promise.all(dates.map(async d=>({d,e:primaryEvent(d),h:await hero(d)})));return`${viewHead('THE DATES I’D LIVE AGAIN','Our movie poster archive.','실제 hero photo만 사용합니다.',back)}<div class="poster-grid">${rows.map(x=>`<button class="poster" data-action="memory" data-date="${x.d}">${x.h?`<img src="${esc(x.h)}" alt="">`:''}<div class="copy"><small>${fmtDate(x.d)}</small><strong>${esc(x.e.title)}</strong></div></button>`).join('')}</div>`}
function wordStats(){const words=['사랑해','보고싶어','여보','아가','평생','결혼','고마워','행복','밥 먹자'],src=state.kakao?.allText||EVENTS.flatMap(e=>e.chat||[]).join('\n');return words.map(w=>({w,n:(src.match(new RegExp(w.replace(/ /g,'\\s*'),'g'))||[]).length}))}
function renderWords(back=''){const stats=wordStats();return`${viewHead('WORDS THAT BECAME OURS','The way we spoke to each other.','KakaoTalk txt를 불러오면 실제 대화 전체 기준으로 다시 계산합니다.',back)}<div class="panel"><div class="word-cloud">${stats.map(x=>`<button class="word-chip" data-size="${x.n>=Math.max(...stats.map(s=>s.n))/2?'lg':''}" data-action="word-detail" data-word="${esc(x.w)}">${esc(x.w)} · ${x.n}</button>`).join('')}</div></div>${kakaoImportCard()}`}
async function renderSeasons(back=''){return`${viewHead('THE SEASONS WE SHARED','Four seasons of us.','계절마다 다른 디자인 언어로 기억을 다시 묶습니다.',back)}<div class="season-grid">${SEASONS.map(s=>`<article class="season-card ${s.id}"><strong>${s.title}</strong><p>${s.sub}</p><div class="date-chips">${s.dates.map(d=>`<button data-action="memory" data-date="${d}">${d.slice(5)}</button>`).join('')}</div></article>`).join('')}</div>`}
function renderFood(back=''){return`${viewHead('OUR LOVE LANGUAGE WAS','“밥 먹자”','맛집 앱이 아니라 함께 먹은 순간을 다시 보는 relationship food journal.',back)}<div class="food-grid">${FOOD_ENTRIES.map(([f,d])=>`<button class="food-card" data-action="memory" data-date="${d}"><strong>${esc(f)}</strong><small>${fmtDate(d)}</small></button>`).join('')}</div>`}
async function renderNumbers(back=''){const photoRecords=await allPhotoRecords(),g=await gratitudeStats(),fav=(await Store.entries('fav:')).filter(([,v])=>v===true).length,values=[['DAYS',Math.max(0,relationshipDay(DAY_300)),'DAY 300'],['PHOTOS',photoRecords.length,'shared archive'],['RECORDED DAYS',uniqueDates().length,'chronology'],['CITIES',CITIES.length,'shared places'],['FIRSTS',FIRSTS.length,'milestones'],['THANK-YOU DAYS',g.days,'both wrote'],['FAVORITES',fav,'heart memories'],['MESSAGES',state.kakao?.total||'—','Kakao import']];return`${viewHead('US, BY THE NUMBERS','A lot can happen in 300 days.','현재 저장 데이터와 실제 Kakao import를 기준으로 계산합니다.',back)}<div class="stats-grid">${values.map(([l,v,s])=>`<div class="stat-card"><strong>${v}</strong><b>${l}</b><span>${s}</span></div>`).join('')}</div>${kakaoImportCard()}`}
function kakaoImportCard(){return`<div class="panel"><span class="panel-label">KAKAO IMPORT</span><h2>실제 KakaoTalk export 분석</h2><p>.txt 파일은 브라우저에서만 parsing합니다. ‘긴장 표현’은 싸움 횟수가 아니라 단순 heuristic입니다.</p><div class="upload-drop"><input type="file" accept=".txt,text/plain" data-action-input="kakao-import">${state.kakao?`<p><b>${state.kakao.total.toLocaleString()} messages parsed.</b></p>`:''}</div></div>`}
function renderPulse(back=''){const months=state.kakao?.months||{},rows=Object.entries(months).sort();return`${viewHead('RELATIONSHIP PULSE','Affection & tension, normalized.','1,000 messages 당 단어 빈도. 긴장 표현은 실제 싸움 횟수가 아닙니다.',back)}${rows.length?`<div class="panel"><div class="month-list">${rows.map(([m,x])=>`<div class="month-row"><span class="date">${m}</span><strong>♡ ${x.affectionRate.toFixed(1)} · △ ${x.tensionRate.toFixed(1)}</strong><span>${x.total.toLocaleString()} msgs</span></div>`).join('')}</div></div>`:'<div class="panel"><p>KakaoTalk .txt를 먼저 불러오면 월별 pulse가 나타납니다.</p></div>'}${kakaoImportCard()}`}
const AWARDS=[['Most walked day',['2025-11-01','2025-12-27']],['Most New York day',['2025-10-04','2025-12-20']],['Most romantic day',['2025-11-13','2025-12-17']],['Funniest day',['2025-12-26','2025-12-31']],['Most “us” day',['2025-12-08','2026-01-17']]];
async function renderAwards(back=''){const votes=await Promise.all(AWARDS.map(async([a])=>[a,await Store.get(`award:${a}`,{})])),map=Object.fromEntries(votes);return`${viewHead('OUR MINI AWARDS','Our tiny award show.','시현과 강원이 각자 투표하고 같으면 MATCH.',back)}<div class="award-grid">${AWARDS.map(([a,ds])=>{const v=map[a]||{},same=v.시현&&v.시현===v.강원;return`<article class="award-card"><h3>${a}</h3>${ds.map(d=>`<button class="award-choice ${v[currentUser()]===d?'active':''}" data-action="award-vote" data-award="${esc(a)}" data-date="${d}">${primaryEvent(d).title} · ${d.slice(5)}</button>`).join('')}${same?'<span class="both-badge">♡ MATCH</span>':''}</article>`}).join('')}</div>`}
async function renderPhotobooth(back=''){const rec=await allPhotoRecords(),booth=[];for(const p of rec){const m=await photoMeta(p.date,p.src);if(m?.type==='네컷')booth.push({...p,meta:m})}return`${viewHead('PHOTOBOOTH ARCHIVE','Keep the strip intact.','네컷은 하나의 완성된 원본 사진으로 취급하고 4장으로 강제 분할하지 않습니다.',back)}<div class="album-grid">${booth.length?booth.map(p=>photoTile(p)).join(''):'<div class="panel"><p>아직 ‘네컷’으로 태그된 사진이 없어요. Photo Album에서 태그를 지정해 주세요.</p></div>'}</div>`}
async function renderFavorites(back=''){const rows=await Store.entries('fav:'),dates=rows.filter(([,v])=>v===true).map(([k])=>k.split(':')[1]).sort();return`${viewHead('OUR FAVORITES ♥','Memories we kept close.','Memory Detail의 ♥ favorite를 누른 날짜.',back)}<div class="month-list">${dates.length?dates.map(d=>`<button class="month-row" data-action="memory" data-date="${d}"><span class="date">${d.slice(5)}</span><strong>${esc(primaryEvent(d).title)}</strong><span>♥</span></button>`).join(''):'<div class="panel">아직 즐겨찾기한 기억이 없어요.</div>'}</div>`}
async function renderLiked(back=''){const rows=await Store.entries('reaction:'),map={};for(const[k,v]of rows){const m=k.match(/^reaction:(\d{4}-\d{2}-\d{2}):(시현|강원)$/);if(m&&v)(map[m[1]]??={})[m[2]]=true}const filter=state.likedFilter||'both',dates=Object.keys(map).filter(d=>filter==='both'?map[d].시현&&map[d].강원:map[d][filter]).sort();return`${viewHead('DAYS WE BOTH LOVED','Our personal likes.','각자 좋아요와 둘 다 좋아한 날을 따로 봅니다.',back)}<div class="view-actions"><button class="pill-btn ${filter==='both'?'active':''}" data-action="liked-filter" data-filter="both">둘 다 좋아한 날</button><button class="pill-btn ${filter==='시현'?'active':''}" data-action="liked-filter" data-filter="시현">시현</button><button class="pill-btn ${filter==='강원'?'active':''}" data-action="liked-filter" data-filter="강원">강원</button></div><div class="month-list" style="margin-top:12px">${dates.length?dates.map(d=>`<button class="month-row" data-action="memory" data-date="${d}"><span class="date">${d.slice(5)}</span><strong>${esc(primaryEvent(d).title)}</strong><span>♡</span></button>`).join(''):'<div class="panel">아직 해당하는 날이 없어요.</div>'}</div>`}
async function renderThanks(back=''){const rows=await Store.entries('gratitude:'),items=rows.map(([k,v])=>{const m=k.match(/^gratitude:(\d{4}-\d{2}-\d{2}):(시현|강원)$/);return m&&v?.text?{date:m[1],user:m[2],text:v.text}:null}).filter(Boolean).sort((a,b)=>b.date.localeCompare(a.date));return`${viewHead('300 DAYS OF 고마워','Things we thanked each other for.','Daily gratitude archive.',back)}<div class="activity-list">${items.length?items.map(x=>`<button class="activity-row" data-action="memory" data-date="${x.date}"><b>${x.date} · ${x.user}</b><span>${esc(x.text)}</span></button>`).join(''):'<div class="panel">아직 쌓인 감사가 없어요.</div>'}</div>`}
function renderBeforeCame(back=''){return`${viewHead('BEFORE / CAME TRUE','Things we once said, then lived.','과거 대화와 실제로 이루어진 순간을 pair로 봅니다.',back)}<div class="grid-2">${BEFORE_CAME_TRUE.map(x=>`<article class="panel"><span class="panel-label">BEFORE · ${x.beforeDate}</span><h2>“${esc(x.before)}”</h2><hr style="border:0;border-top:1px solid var(--line)"><span class="panel-label">CAME TRUE · ${x.cameDate}</span><h2>${esc(x.came)}</h2><button class="secondary-btn" data-action="memory" data-date="${x.cameDate}">Open memory →</button></article>`).join('')}</div>`}
function renderFunny(back=''){const lines=EVENTS.flatMap(e=>(e.chat||[]).filter(x=>/ㅋㅋ|ㅎㅎ|졸업이나|뷔페|뻗/.test(x)).map(text=>({date:e.date,text})));return`${viewHead('FUNNY & INSIDE JOKES','The unserious parts of us.','실제 저장된 문구만 사용합니다.',back)}<div class="activity-list">${lines.map(x=>`<button class="activity-row" data-action="memory" data-date="${x.date}"><b>${x.date}</b><span>${esc(x.text)}</span></button>`).join('')}</div>`}
async function allPhotoRecords(){const keys=await Store.keys('photos:'),out=[];for(const k of keys){const date=k.slice(7),arr=await Store.get(k,[]);for(const src of(Array.isArray(arr)?arr:[]))out.push({date,src,title:primaryEvent(date).title})}return out.sort((a,b)=>b.date.localeCompare(a.date))}
async function renderAlbum(back=''){let rec=await allPhotoRecords(),enriched=[];for(const p of rec)enriched.push({...p,meta:await photoMeta(p.date,p.src),hero:(await hero(p.date))===p.src,book:await Store.get(Keys.bookPick(p.date,photoId(p.src)),false)});rec=enriched;const q=state.albumSearch.toLowerCase();rec=rec.filter(p=>{const m=p.meta||{},hay=[p.date,p.title,m.place,m.food,m.type,m.caption,...(m.moods||[])].filter(Boolean).join(' ').toLowerCase();return(!q||hay.includes(q))&&(!state.albumType||m.type===state.albumType)});if(state.albumMode==='book')rec=rec.filter(p=>p.book);if(state.albumMode==='places')rec=rec.filter(p=>p.meta?.place);const toolbar=`<div class="album-toolbar"><input class="search-input" data-action-input="album-search" value="${esc(state.albumSearch)}" placeholder="날짜 · 장소 · 음식 · 느낌 · 캡션 검색"><select class="search-input" data-action-input="album-type"><option value="">모든 종류</option>${['셀카','커플사진','인물','풍경','음식','티켓/물건','스크린샷','네컷'].map(t=>`<option ${state.albumType===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="view-actions">${[['story','STORY'],['day','BY DAY'],['places','PLACES'],['book','BOOK PICKS'],['contact','CONTACT SHEET']].map(([id,l])=>`<button class="pill-btn ${state.albumMode===id?'active':''}" data-action="album-mode" data-mode="${id}">${l}</button>`).join('')}<button class="pill-btn" data-action="upload" data-date="${todayISO()}">+ ADD PHOTOS</button></div>`;let body='';if(state.albumMode==='contact')body=`<div class="contact-sheet">${rec.map(p=>`<button data-action="lightbox" data-src="${esc(p.src)}"><img src="${esc(p.src)}" alt=""></button>`).join('')}</div>`;else if(state.albumMode==='day'){const by={};rec.forEach(p=>(by[p.date]??=[]).push(p));body=Object.entries(by).map(([d,ps])=>`<section class="panel"><span class="panel-label">${d}</span><h2>${esc(primaryEvent(d).title)}</h2><div class="album-grid">${ps.map(photoTile).join('')}</div></section>`).join('')||'<div class="panel">아직 사진이 없어요.</div>'}else body=`<div class="album-grid">${rec.length?rec.map(photoTile).join(''):'<div class="panel">아직 사진이 없어요.</div>'}</div>`;return`${viewHead('OUR PHOTO ALBUM','A book that keeps growing.','실제 사진 전체를 날짜·장소·Book Pick·contact sheet로 다시 봅니다.',back)}${toolbar}<div style="margin-top:12px">${body}</div>`}
function photoTile(p){const m=p.meta||{};return`<article class="photo-tile"><button class="img-btn" data-action="lightbox" data-src="${esc(p.src)}"><img src="${esc(p.src)}" alt="${esc(m.caption||p.title)}"></button><div class="photo-actions"><button class="${p.hero?'active':''}" data-action="set-hero" data-date="${p.date}" data-src="${esc(p.src)}">★ HERO</button><button class="${p.book?'active':''}" data-action="book-pick" data-date="${p.date}" data-src="${esc(p.src)}">B BOOK PICK</button><button data-action="photo-meta" data-date="${p.date}" data-src="${esc(p.src)}">✎ TAG</button></div><div class="photo-meta">${esc([m.place,m.food,m.type,...(m.moods||[]),m.caption].filter(Boolean).join(' · ')||p.date)}</div></article>`}
async function renderFuture(){const tabs=`<div class="future-tabs">${[['postcards','Postcards to Us Again','다시 가고 싶은 곳'],['bucket','Someday, With You','앞으로 함께 할 것'],['letters','Letter to Future Us','미래에 열 편지']].map(([id,t,s])=>`<button class="${state.futureTab===id?'active':''}" data-action="future-tab" data-tab="${id}"><b>${t}</b>${s}</button>`).join('')}</div>`;let body='';if(state.futureTab==='postcards')body=await futurePostcards();if(state.futureTab==='bucket')body=await futureBucket();if(state.futureTab==='letters')body=await futureLetters();return`${viewHead('OUR FUTURE','Still becoming us.','다시 돌아갈 곳, 함께 해볼 것, 미래의 우리에게 남길 편지. 세 축으로 정리합니다.')}${tabs}${body}`}
async function futurePostcards(){let items=await Store.get('comebackplaces',null);if(!Array.isArray(items)||!items.length)items=[{id:'c1',text:'MoMA',reason:''},{id:'c2',text:'Raku',reason:''},{id:'c3',text:'Beacon',reason:''},{id:'c4',text:'San Diego',reason:''}];items=items.map(x=>typeof x==='string'?{id:'c'+Math.random(),text:x,reason:''}:x);return`<div class="postcard-grid">${items.map(x=>`<article class="postcard"><h3>${esc(x.text)}</h3><span class="panel-label">WHY WE'D RETURN</span><textarea data-action-input="postcard-reason" data-id="${esc(x.id)}" placeholder="왜 다시 가고 싶은지…">${esc(x.reason||'')}</textarea><button class="delete-btn" data-action="postcard-delete" data-id="${esc(x.id)}">×</button></article>`).join('')}</div><div class="add-row"><input id="postcard-add" placeholder="다시 가고 싶은 장소"><button class="primary-btn" data-action="postcard-add">추가</button></div>`}
const GROUPS={places:['PLACES','같이 가고 싶은 장소'],little:['LITTLE THINGS','평범한 일상'],try:['THINGS TO TRY','같이 해보고 싶은 것'],years:['YEARS AHEAD','오래 뒤의 미래']};
async function futureBucket(){let items=await Store.get('futurebucket:v26',null);if(!Array.isArray(items)||!items.length)items=[{id:'b1',text:'같이 장보기',done:false,group:'little'},{id:'b2',text:'크리스마스 트리 같이 꾸미기',done:false,group:'little'},{id:'b3',text:'New York, again',done:false,group:'places'},{id:'b4',text:'겨울방학 여행',done:false,group:'try'},{id:'b5',text:'결혼 준비도 천천히 같이 하기',done:false,group:'years'}];return`<div class="bucket-groups">${Object.entries(GROUPS).map(([g,[t,s]])=>`<section class="bucket-group"><h3>${t}</h3><p>${s}</p>${items.filter(x=>(x.group||'little')===g).map(x=>`<div class="bucket-item ${x.done?'done':''}"><button class="check-btn" data-action="bucket-toggle" data-id="${esc(x.id)}">${x.done?'✓':''}</button><span class="bucket-text">${esc(x.text)}</span><button class="delete-btn" style="position:static" data-action="bucket-delete" data-id="${esc(x.id)}">×</button></div>`).join('')}<div class="add-row"><input data-bucket-input="${g}" placeholder="새 항목"><button class="primary-btn" data-action="bucket-add" data-group="${g}">+</button></div></section>`).join('')}</div>`}
async function futureLetters(){const items=await Store.get('futureletters:v26',[]),today=todayISO();return`<div class="letter-layout"><aside class="envelope-card"><div class="envelope-visual">✉</div><h2>Write now. Open later.</h2><p>열 날짜 이전에는 내용이 잠겨 있어요.</p></aside><section class="letter-compose"><div class="field"><label>미래의 우리에게</label><textarea id="future-letter-text" placeholder="미래의 우리에게 지금의 마음을…"></textarea></div><div class="field"><label>OPEN DATE</label><input id="future-letter-date" type="date" min="${today}"></div><button class="primary-btn" style="width:100%;margin-top:10px" data-action="letter-seal">Seal this letter</button><div class="letter-list">${items.map(x=>{const open=today>=x.openDate;return`<div class="letter-row"><div><strong>${open?'OPEN':'SEALED'} · ${esc(x.openDate)}</strong><small>${open?'이제 열 수 있어요.':'아직 기다리는 중.'}</small>${x.opened?`<div class="letter-open">${esc(x.text)}</div>`:''}</div><button class="secondary-btn" data-action="letter-open" data-id="${esc(x.id)}" ${open?'':'disabled'}>${x.opened?'Close':'Open'}</button></div>`}).join('')}</div></section></div>`}
async function openMemory(date){const evs=eventForDate(date),ev=evs[0]||{date,title:'Our Day',chapter:'continue',story:'아직 사건 설명이 없는 날짜입니다.'},ps=await photos(date),h=await hero(date),fav=await Store.get(Keys.favorite(date),false),ru=await Store.get(Keys.reaction(date,currentUser()),false),rp=await Store.get(Keys.reaction(date,otherUser()),false),note=await Store.get(Keys.note(date),''),comments=await Store.get(Keys.comments(date),[]),comp=await completion(date),q=questionFor(date),chats=[...new Set(evs.flatMap(x=>x.chat||[]))],dates=uniqueDates(),idx=dates.indexOf(date),prev=dates[idx-1],next=dates[idx+1];setOverlay(`<div class="overlay" data-action="overlay-bg"><article class="modal"><header class="modal-head"><span class="hand">${esc(chapterBy(ev.chapter).label)}</span><div><button class="reaction-btn ${fav?'active':''}" data-action="favorite" data-date="${date}">♥ Favorite</button> <button class="close-btn" data-action="close">×</button></div></header><div class="modal-body"><section class="memory-title"><div><span class="memory-date">${fmtDate(date)} · ${weekday(date)} · DAY ${relationshipDay(date)}</span><h2>${esc(evs.map(x=>x.title).join(' · '))}</h2></div><div class="reaction-row"><button class="reaction-btn ${ru?'active':''}" data-action="reaction" data-date="${date}" data-user="${currentUser()}">${currentUser()} ${ru?'♥':'🤍'}</button><span class="reaction-btn ${rp?'active':''}">${otherUser()} ${rp?'♥':'🤍'}</span></div></section>${evs.map(x=>`<p class="memory-story"><b>${esc(x.title)}</b><br>${esc(x.story)}</p>`).join('')}${chats.length?`<section class="panel"><span class="panel-label">KAKAOTALK · ORIGINAL TEXT</span><div class="chat-stack">${chats.map(c=>`<div class="chat-bubble">${esc(c)}</div>`).join('')}</div></section>`:''}<section class="panel"><span class="panel-label">PHOTOS</span><div class="save-row"><h2>사진</h2><button class="secondary-btn" data-action="upload" data-date="${date}">+ ADD PHOTOS</button></div><div class="memory-photos">${ps.length?ps.map(src=>`<div class="photo-box"><button style="border:0;background:transparent;padding:0;width:100%;height:100%" data-action="lightbox" data-src="${esc(src)}"><img src="${esc(src)}" alt=""></button></div>`).join(''):Array.from({length:3},()=>`<div class="photo-box">${emptyPhoto('PHOTO SLOT')}</div>`).join('')}</div>${h?'<p class="hand">★ HERO PHOTO is set.</p>':'<p class="hand">첫 사진을 추가하면 hero로 자동 설정됩니다.</p>'}</section>${await dailyCardHTML(date,comp,q)}<section class="panel"><span class="panel-label">MY NOTE</span><div class="field"><textarea id="memory-note" data-date="${date}" placeholder="이 날의 기억에 한 줄 더…">${esc(note||'')}</textarea></div><span id="note-state" class="saved-label"></span></section><section class="panel"><span class="panel-label">COMMENTS</span><div class="comments">${comments.length?comments.map(c=>`<div class="comment"><b>${esc(c.author)}</b><p>${esc(c.text)}</p><small>${new Date(c.time).toLocaleString('ko-KR')}</small></div>`).join(''):'<p>아직 댓글이 없어요.</p>'}</div><div class="comment-form"><input id="comment-input" placeholder="이 날의 기억에 댓글 남기기"><button class="primary-btn" data-action="comment" data-date="${date}">남기기</button></div></section><div class="memory-nav"><button class="secondary-btn" ${prev?'data-action="memory" data-date="'+prev+'"':'disabled'}>◀ 이전 기억</button><button class="secondary-btn" ${next?'data-action="memory" data-date="'+next+'"':'disabled'}>다음 기억 ▶</button></div></div></article></div>`)}
async function dailyCardHTML(date,comp,q){const s=comp.시현,g=comp.강원;return`<section class="panel"><span class="panel-label">DAILY CARD · ${fmtDate(date)}</span><h2>${comp.total===6?'A day we kept.':'This day is still being written.'}</h2><div class="daily-card-grid"><div class="daily-card-block"><b>OUR DAY</b><p>시현 · ${esc(s.checkin?.line||s.line?.text||'—')}\n강원 · ${esc(g.checkin?.line||g.line?.text||'—')}</p></div><div class="daily-card-block"><b>TODAY'S THANK YOU</b><p>시현 → 강원 · ${esc(s.g?.text||'—')}\n강원 → 시현 · ${esc(g.g?.text||'—')}</p></div><div class="daily-card-block"><b>TODAY'S QUESTION</b><p>${esc(q.text)}\n\n시현 · ${esc(s.q?.text||'—')}\n강원 · ${esc(g.q?.text||'—')}</p></div></div><p>${comp.total}/6 complete</p></section>`}
function openUpload(date){setOverlay(`<div class="overlay"><article class="modal sm"><header class="modal-head"><b>ADD PHOTOS · ${date}</b><button class="close-btn" data-action="close">×</button></header><div class="modal-body"><h2>Save this day as it looked.</h2><div class="upload-drop"><p>실제 원본 사진만 저장합니다. 가능한 경우 Firebase Storage에 원본 파일 그대로 업로드합니다.</p><input id="photo-files" type="file" accept="image/*" multiple><div id="upload-list" class="upload-list"></div></div><button class="primary-btn" style="width:100%;margin-top:12px" data-action="upload-run" data-date="${date}">사진 저장</button></div></article></div>`)}
async function runUpload(date){const input=$('#photo-files'),files=[...(input?.files||[])];if(!files.length)return toast('사진을 먼저 선택해 주세요.');const list=$('#upload-list');let arr=await photos(date),h=await hero(date);for(const[i,file]of files.entries()){const row=document.createElement('div');row.className='upload-file';row.textContent=`${i+1}/${files.length} · ${file.name} · 업로드 중…`;list.append(row);try{const url=await Store.uploadPhoto(file,date);arr.push(url);await Store.set(Keys.photos(date),arr);if(!h){h=url;await Store.set(Keys.hero(date),url)}row.textContent=`${file.name} · 저장됨 ✓`;await Store.log('photo',date,currentUser(),`${file.name} 사진을 추가했어요`)}catch(err){row.textContent=`${file.name} · 실패 (${err.message})`}}toast('사진 저장을 마쳤어요');setTimeout(async()=>{closeOverlay();await renderView()},500)}
function openLightbox(src){setOverlay(`<div class="lightbox"><img src="${esc(src)}" alt="원본 사진"><button data-action="close">×</button></div>`)}
async function openMeta(date,src){const m=await photoMeta(date,src)||{place:'',food:'',type:'',moods:[],caption:''},moods=['설렘','다정함','웃김','평범한 일상','여행','뉴욕 감성','따뜻함','겨울','여름','밤','노을','기념일','보고싶은 순간','최애'];setOverlay(`<div class="overlay"><article class="modal sm"><header class="modal-head"><b>ABOUT THIS PHOTO</b><button class="close-btn" data-action="close">×</button></header><div class="modal-body"><div class="photo-box" style="height:260px"><img src="${esc(src)}" alt=""></div><div class="field"><label>장소</label><input id="meta-place" value="${esc(m.place||'')}"></div><div class="field"><label>음식 / 메뉴</label><input id="meta-food" value="${esc(m.food||'')}"></div><div class="field"><label>사진 종류</label><select id="meta-type"><option value="">선택</option>${['셀카','커플사진','인물','풍경','음식','티켓/물건','스크린샷','네컷'].map(t=>`<option ${m.type===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="field"><label>느낌 · 복수 선택</label><div class="mood-grid">${moods.map(x=>`<label class="mood-btn"><input type="checkbox" name="meta-mood" value="${x}" ${(m.moods||[]).includes(x)?'checked':''}> ${x}</label>`).join('')}</div></div><div class="field"><label>한 줄 캡션</label><input id="meta-caption" value="${esc(m.caption||'')}"></div><button class="primary-btn" style="width:100%;margin-top:10px" data-action="photo-meta-save" data-date="${date}" data-src="${esc(src)}">SAVE TAGS</button></div></article></div>`)}
function searchPanel(q){const results=searchMemories(q);return`<div class="panel"><input id="global-search-input" class="search-input" style="width:100%" value="${esc(q)}" placeholder="추억 검색 — 첫눈, MoMA, 사랑해, 부산…"><div id="search-results" class="search-results">${resultsHTML(results)}</div></div>`}function searchMemories(q){q=String(q||'').trim().toLowerCase();if(!q)return[];return EVENTS.filter(e=>[e.date,e.title,e.chapter,e.story,e.location,...(e.chat||[])].filter(Boolean).join(' ').toLowerCase().includes(q)).slice(0,40)}function resultsHTML(results){return results.length?results.map(e=>`<button class="search-result" data-action="memory" data-date="${e.date}"><small>${e.date} · ${esc(chapterBy(e.chapter).label)}</small><strong>${esc(e.title)}</strong><span>${esc((e.story||'').slice(0,100))}</span></button>`).join(''):'<p>검색어를 입력하면 실제 연대기와 카톡 문구에서 찾아요.</p>'}
function openSearch(){setOverlay(`<div class="overlay"><article class="modal sm"><header class="modal-head"><b>GLOBAL MEMORY SEARCH</b><button class="close-btn" data-action="close">×</button></header><div class="modal-body">${searchPanel('')}</div></article></div>`);setTimeout(()=>$('#global-search-input')?.focus(),50)}
function openActivity(){localStorage.setItem('clean300_activity_read',String(Date.now()));updateActivityBadge();setOverlay(`<div class="overlay"><article class="modal sm"><header class="modal-head"><b>OUR ACTIVITY</b><button class="close-btn" data-action="close">×</button></header><div class="modal-body"><div class="activity-modal-list">${state.activity.length?state.activity.map(a=>`<button class="activity-row" data-action="memory" data-date="${esc(a.date||todayISO())}"><b>${esc(a.author||'우리')} · ${esc(activityLabel(a.type))}</b><span>${esc(a.text||'')}</span></button>`).join(''):'<p>아직 새 활동이 없어요.</p>'}</div></div></article></div>`)}
function updateActivityBadge(){const read=Number(localStorage.getItem('clean300_activity_read')||0),n=state.activity.filter(a=>(a.clientTime||0)>read&&a.author!==currentUser()).length,b=$('#activity-badge');if(!b)return;b.textContent=n;b.classList.toggle('is-hidden',!n)}
async function identityHash(pin,salt){const material=await crypto.subtle.importKey('raw',new TextEncoder().encode(pin),'PBKDF2',false,['deriveBits']),bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt:new TextEncoder().encode(salt),iterations:120000,hash:'SHA-256'},material,256);return[...new Uint8Array(bits)].map(b=>b.toString(16).padStart(2,'0')).join('')}function newSalt(){const b=new Uint8Array(16);crypto.getRandomValues(b);return[...b].map(x=>x.toString(16).padStart(2,'0')).join('')}
async function showIdentity(mode='first'){$('#identity-gate').classList.remove('is-hidden');const st=$('#identity-stage'),copy=$('#identity-copy');copy.textContent=mode==='switch'?'기록할 사람을 선택해 주세요. 다른 사람으로 전환할 때는 그 사람 PIN을 확인해요.':'이 기기에서 기록을 남길 사람을 한 번만 선택해 주세요.';st.innerHTML=`<div class="identity-choice">${USERS.map(u=>`<button data-action="identity-user" data-user="${u}" data-mode="${mode}"><span class="avatar">${u[0]}</span><strong>${u}으로 기록하기</strong></button>`).join('')}</div>`}
async function identityUser(user,mode){const rec=await Store.get(Keys.identityPin(user),null),st=$('#identity-stage');st.innerHTML=`<div class="pin-box"><p><b>${user}</b> · ${rec?'PIN 확인':'처음 PIN 만들기'}</p><input id="pin-input" type="password" inputmode="numeric" maxlength="4" placeholder="••••"><div class="pin-actions"><button class="secondary-btn" data-action="identity-back" data-mode="${mode}">뒤로</button><button class="primary-btn" data-action="identity-pin" data-user="${user}" data-mode="${mode}" data-has="${rec?'1':'0'}">${rec?'확인':'PIN 저장'}</button></div><p id="pin-error" class="form-error"></p><small>PIN 원문은 저장하지 않습니다.</small></div>`;setTimeout(()=>$('#pin-input')?.focus(),30)}
async function identityPin(user,mode,has){const pin=($('#pin-input')?.value||'').replace(/\D/g,'').slice(0,4);if(!/^\d{4}$/.test(pin))return $('#pin-error').textContent='숫자 4자리로 입력해 주세요.';try{if(has){const rec=await Store.get(Keys.identityPin(user),null);if(!rec||await identityHash(pin,rec.salt)!==rec.hash)return $('#pin-error').textContent='PIN이 맞지 않아요.'}else{const salt=newSalt(),hash=await identityHash(pin,salt);await Store.set(Keys.identityPin(user),{salt,hash,createdAt:Date.now()})}state.user=user;localStorage.setItem('clean300_identity',user);localStorage.setItem('v25_identity_user',user);$('#identity-gate').classList.add('is-hidden');updateIdentityPill();toast(`${user}으로 기록할게요 ♡`);await renderView()}catch(e){$('#pin-error').textContent='PIN을 저장하거나 확인하지 못했어요.'}}
function updateIdentityPill(){const p=$('#identity-pill');if(p)p.textContent=`WRITING AS · ${currentUser()}`;updateActivityBadge()}
function parseKakao(text){const lines=text.split(/\r?\n/),msgRe=/^\[([^\]]+)\] \[(오전|오후) [^\]]+\] (.*)$/;let currentDate='',total=0,all=[],months={};for(const line of lines){const dm=line.match(/^-+ (\d{4})년 (\d{1,2})월 (\d{1,2})일/);if(dm){currentDate=`${dm[1]}-${pad(dm[2])}-${pad(dm[3])}`;continue}const m=line.match(msgRe);if(!m||!currentDate)continue;const text=m[3];total++;all.push(text);const ym=currentDate.slice(0,7),o=months[ym]??={total:0,words:{},affection:0,tension:0,affectionRate:0,tensionRate:0};o.total++;for(const w of['사랑해','보고싶어','여보','아가','고마워','행복']){const n=(text.match(new RegExp(w,'g'))||[]).length;o.words[w]=(o.words[w]||0)+n;o.affection+=n}for(const w of['서운','미안','화나','싸우','속상','힘들'])o.tension+=(text.match(new RegExp(w,'g'))||[]).length}for(const o of Object.values(months)){o.affectionRate=o.total?o.affection/o.total*1000:0;o.tensionRate=o.total?o.tension/o.total*1000:0}return{total,allText:all.join('\n'),months}}
function registerPWA(){if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{})}
async function reminderTick(){if(localStorage.getItem('clean300_daily_reminder')!=='1')return;const t=localStorage.getItem('clean300_reminder_time')||'21:30',[h,m]=t.split(':').map(Number),now=new Date();if(now.getHours()<h||(now.getHours()===h&&now.getMinutes()<m))return;const date=todayISO(),last=localStorage.getItem('clean300_reminder_last');if(last===date)return;const c=await completion(date),u=currentUser(),s=c[u];if(s.record&&s.gratitude&&s.question)return;const title='오늘 우리 하루가 아직 열려 있어요 ♡',body='오늘 기록 · 감사 · 질문을 남기면 Daily Card가 완성돼요.';toast(title);if(Notification.permission==='granted')new Notification(title,{body});localStorage.setItem('clean300_reminder_last',date)}
function maybePartnerNotification(rows){if(localStorage.getItem('clean300_partner_notify')!=='1'||Notification.permission!=='granted')return;const last=Number(localStorage.getItem('clean300_partner_seen')||Date.now()),hit=rows.find(a=>(a.clientTime||0)>last&&a.author===otherUser());if(hit){new Notification(`${hit.author} · ${activityLabel(hit.type)}`,{body:(hit.text||'새 활동이 있어요.').slice(0,90)});localStorage.setItem('clean300_partner_seen',String(Date.now()))}}
async function handleClick(e){const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(a==='overlay-bg'&&e.target===b)return closeOverlay();if(a==='view')return routeTo(b.dataset.target);if(a==='memory')return openMemory(b.dataset.date);if(a==='close')return closeOverlay();if(a==='special')return routeTo('special',b.dataset.feature);if(a==='special-back')return routeTo('special');if(a==='open-search')return openSearch();if(a==='open-activity')return openActivity();if(a==='switch-identity')return showIdentity('switch');if(a==='identity-user')return identityUser(b.dataset.user,b.dataset.mode);if(a==='identity-back')return showIdentity(b.dataset.mode);if(a==='identity-pin')return identityPin(b.dataset.user,b.dataset.mode,b.dataset.has==='1');if(a==='days-mode'){state.daysMode=b.dataset.mode;return renderView()}if(a==='month-shift'){state.month=new Date(state.month.getFullYear(),state.month.getMonth()+Number(b.dataset.delta),1);return renderView()}if(a==='mood'){state.selectedMood=b.dataset.value;$$('.mood-btn').forEach(x=>x.classList.toggle('active',x.dataset.value===state.selectedMood));return}if(a==='save-day'){const date=todayISO(),line=$('#diary-line')?.value.trim()||'';await Store.set(Keys.daily(date,currentUser()),{mood:state.selectedMood,line,savedAt:Date.now()});await Store.set(Keys.dailyLine(date,currentUser()),{author:currentUser(),text:line,savedAt:Date.now()});await Store.log('record',date,currentUser(),line||state.selectedMood);toast('오늘 기록을 저장했어요');return renderView()}if(a==='save-gratitude'){const date=todayISO(),text=$('#gratitude-input')?.value.trim()||'';await Store.set(Keys.gratitude(date,currentUser()),{text,savedAt:Date.now()});await Store.log('gratitude',date,currentUser(),text);toast('오늘의 감사를 남겼어요 ♡');return renderView()}if(a==='save-question'){const date=todayISO(),text=$('#question-input')?.value.trim()||'';await Store.set(Keys.answer(date,currentUser()),{questionId:Number(b.dataset.qid),text,savedAt:Date.now()});await Store.log('question',date,currentUser(),text);toast('오늘 질문에 답했어요');return renderView()}if(a==='upload')return openUpload(b.dataset.date||todayISO());if(a==='upload-run')return runUpload(b.dataset.date);if(a==='lightbox')return openLightbox(b.dataset.src);if(a==='photo-meta')return openMeta(b.dataset.date,b.dataset.src);if(a==='photo-meta-save'){const moods=$$('input[name="meta-mood"]:checked').map(x=>x.value),meta={place:$('#meta-place').value.trim(),food:$('#meta-food').value.trim(),type:$('#meta-type').value,caption:$('#meta-caption').value.trim(),moods};await setPhotoMeta(b.dataset.date,b.dataset.src,meta);toast('사진 태그를 저장했어요');closeOverlay();return renderView()}if(a==='set-hero'){await Store.set(Keys.hero(b.dataset.date),b.dataset.src);toast('HERO PHOTO로 설정했어요');return renderView()}if(a==='book-pick'){const k=Keys.bookPick(b.dataset.date,photoId(b.dataset.src)),v=await Store.get(k,false);await Store.set(k,!v);toast(!v?'BOOK PICK에 담았어요':'BOOK PICK에서 뺐어요');return renderView()}if(a==='album-mode'){state.albumMode=b.dataset.mode;return renderView()}if(a==='favorite'){const v=await Store.get(Keys.favorite(b.dataset.date),false);await Store.set(Keys.favorite(b.dataset.date),!v);return openMemory(b.dataset.date)}if(a==='reaction'){const k=Keys.reaction(b.dataset.date,currentUser()),v=await Store.get(k,false);await Store.set(k,!v);return openMemory(b.dataset.date)}if(a==='comment'){const input=$('#comment-input'),text=input?.value.trim();if(!text)return;const rows=await Store.get(Keys.comments(b.dataset.date),[]);rows.push({author:currentUser(),text,time:Date.now()});await Store.set(Keys.comments(b.dataset.date),rows);await Store.log('comment',b.dataset.date,currentUser(),text);toast('댓글을 남겼어요');return openMemory(b.dataset.date)}if(a==='future-tab'){state.futureTab=b.dataset.tab;return renderView()}if(a==='postcard-add'){const input=$('#postcard-add'),text=input?.value.trim();if(!text)return;let items=await Store.get('comebackplaces',[]);if(!Array.isArray(items))items=[];items.push({id:'c'+Date.now(),text,reason:''});await Store.set('comebackplaces',items);await Store.log('future',todayISO(),currentUser(),`${text}를 다시 가고 싶은 곳에 추가했어요`);return renderView()}if(a==='postcard-delete'){let items=await Store.get('comebackplaces',[]);items=items.filter(x=>String(x.id)!==b.dataset.id);await Store.set('comebackplaces',items);return renderView()}if(a==='bucket-toggle'||a==='bucket-delete'||a==='bucket-add'){let items=await Store.get('futurebucket:v26',[]);if(!Array.isArray(items))items=[];if(a==='bucket-toggle'){const x=items.find(x=>String(x.id)===b.dataset.id);if(x)x.done=!x.done}if(a==='bucket-delete')items=items.filter(x=>String(x.id)!==b.dataset.id);if(a==='bucket-add'){const input=$(`[data-bucket-input="${b.dataset.group}"]`),text=input?.value.trim();if(text)items.push({id:'b'+Date.now(),text,done:false,group:b.dataset.group})}await Store.set('futurebucket:v26',items);await Store.log('future',todayISO(),currentUser(),'Bucket list를 수정했어요');return renderView()}if(a==='letter-seal'){const text=$('#future-letter-text')?.value.trim(),openDate=$('#future-letter-date')?.value;if(!text||!openDate)return toast('편지와 열 날짜를 모두 적어 주세요.');const items=await Store.get('futureletters:v26',[]);items.push({id:'l'+Date.now(),text,openDate,createdAt:Date.now(),author:currentUser(),opened:false});await Store.set('futureletters:v26',items);await Store.log('future',todayISO(),currentUser(),`미래 편지를 봉인했어요 · ${openDate}`);toast('편지를 봉인했어요 ✉');return renderView()}if(a==='letter-open'){const items=await Store.get('futureletters:v26',[]),x=items.find(x=>String(x.id)===b.dataset.id);if(x&&todayISO()>=x.openDate)x.opened=!x.opened;await Store.set('futureletters:v26',items);return renderView()}if(a==='award-vote'){const v=await Store.get(`award:${b.dataset.award}`,{});v[currentUser()]=b.dataset.date;await Store.set(`award:${b.dataset.award}`,v);return renderView()}if(a==='liked-filter'){state.likedFilter=b.dataset.filter;return renderView()}if(a==='word-detail')return openWordDetail(b.dataset.word);if(a==='city-search'){routeTo('special','search');return}if(a==='notification-permission'){if('Notification'in window){const p=await Notification.requestPermission();toast(`알림 권한: ${p}`)}return}if(a==='toggle-music')return toggleMusic()}
async function handleInput(e){const el=e.target;if(el.matches('[data-action-input="postcard-reason"]')){clearTimeout(el._t);el._t=setTimeout(async()=>{let items=await Store.get('comebackplaces',[]),x=items.find(x=>String(x.id)===el.dataset.id);if(x){x.reason=el.value;await Store.set('comebackplaces',items)}},450)}if(el.matches('[data-action-input="album-search"]')){state.albumSearch=el.value;clearTimeout(el._t);el._t=setTimeout(()=>renderView(),250)}if(el.matches('[data-action-input="album-type"]')){state.albumType=el.value;renderView()}if(el.id==='global-search-input')$('#search-results').innerHTML=resultsHTML(searchMemories(el.value));if(el.id==='memory-note'){clearTimeout(el._t);el._t=setTimeout(async()=>{await Store.set(Keys.note(el.dataset.date),el.value);const s=$('#note-state');if(s)s.textContent='자동 저장됨 ✓'},400)}}
async function handleChange(e){const el=e.target;if(el.matches('[data-setting="daily"]')){localStorage.setItem('clean300_daily_reminder',el.checked?'1':'0');toast(el.checked?'Daily reminder ON':'Daily reminder OFF')}if(el.matches('[data-setting="partner"]')){localStorage.setItem('clean300_partner_notify',el.checked?'1':'0');localStorage.setItem('clean300_partner_seen',String(Date.now()));toast(el.checked?'상대방 활동 알림 ON':'상대방 활동 알림 OFF')}if(el.matches('[data-setting="time"]'))localStorage.setItem('clean300_reminder_time',el.value);if(el.matches('[data-action-input="kakao-import"]')){const file=el.files?.[0];if(!file)return;state.kakao=parseKakao(await file.text());toast(`${state.kakao.total.toLocaleString()} messages parsed`);return renderView()}}
async function handleSubmit(e){if(e.target.id==='lock-form'){e.preventDefault();const v=$('#lock-input').value.trim();if(v==='1023'){sessionStorage.setItem('clean300_unlocked','1');$('#lock-screen').classList.add('is-hidden');await bootAfterUnlock()}else $('#lock-error').textContent='날짜가 맞지 않아요.'}}
function openWordDetail(word){const src=state.kakao?.allText?state.kakao.allText.split('\n'):EVENTS.flatMap(e=>(e.chat||[]).map(c=>`${e.date} ${c}`)),rows=src.filter(x=>x.includes(word)).slice(0,80);setOverlay(`<div class="overlay"><article class="modal sm"><header class="modal-head"><b>${esc(word)}</b><button class="close-btn" data-action="close">×</button></header><div class="modal-body"><p>${rows.length} matching lines shown.</p><div class="activity-list">${rows.map(x=>`<div class="activity-row"><span>${esc(x)}</span></div>`).join('')}</div></div></article></div>`)}
function toggleMusic(){const audio=$('#bgm'),btn=$('#music-button');if(audio.paused)audio.play().then(()=>{btn.classList.add('playing');localStorage.setItem('clean300_music','1')}).catch(()=>toast('화면을 한 번 더 눌러 재생해 주세요.'));else{audio.pause();btn.classList.remove('playing');localStorage.setItem('clean300_music','0')}}
async function bootAfterUnlock(){$('#app').classList.remove('is-hidden');if(!state.user)await showIdentity('first');else updateIdentityPill();if(!location.hash)location.hash='#/home';else await applyRoute();if(localStorage.getItem('clean300_music')==='1')$('#bgm').play().then(()=>$('#music-button').classList.add('playing')).catch(()=>{})}
async function init(){registerPWA();document.addEventListener('click',handleClick);document.addEventListener('input',handleInput);document.addEventListener('change',handleChange);document.addEventListener('submit',handleSubmit);window.addEventListener('hashchange',applyRoute);Store.subscribeActivity(rows=>{const firstLoad=state.activity.length===0;state.activity=rows||[];updateActivityBadge();if(!firstLoad)maybePartnerNotification(state.activity);if(state.view==='home')renderView()});setInterval(reminderTick,60000);if(sessionStorage.getItem('clean300_unlocked')==='1'){$('#lock-screen').classList.add('is-hidden');await bootAfterUnlock()}else $('#lock-input')?.focus()}
init();
